const NETWORKS=Object.freeze({'1':{name:'Ethereum',symbol:'ETH'},'56':{name:'BNB Smart Chain',symbol:'BNB'},'42161':{name:'Arbitrum One',symbol:'ETH'},'8453':{name:'Base',symbol:'ETH'},'10':{name:'OP Mainnet',symbol:'ETH'},'137':{name:'Polygon PoS',symbol:'POL'},'100':{name:'Gnosis',symbol:'xDAI'},'43114':{name:'Avalanche C-Chain',symbol:'AVAX'},'14':{name:'Flare',symbol:'FLR'},'25':{name:'Cronos',symbol:'CRO'},'30':{name:'Rootstock',symbol:'RBTC'},'109':{name:'Shibarium',symbol:'BONE'},'130':{name:'Unichain',symbol:'ETH'},'143':{name:'Monad',symbol:'MON'},'146':{name:'Sonic',symbol:'S'},'169':{name:'Manta Pacific',symbol:'ETH'},'204':{name:'opBNB',symbol:'BNB'},'250':{name:'Fantom Opera',symbol:'FTM'},'252':{name:'Fraxtal',symbol:'FRAX'},'288':{name:'Boba Network',symbol:'ETH'},'324':{name:'zkSync Era',symbol:'ETH'},'480':{name:'World Chain',symbol:'ETH'},'592':{name:'Astar',symbol:'ASTR'},'1088':{name:'Metis Andromeda',symbol:'METIS'},'1101':{name:'Polygon zkEVM',symbol:'ETH'},'1116':{name:'Core',symbol:'CORE'},'1135':{name:'Lisk',symbol:'ETH'},'1284':{name:'Moonbeam',symbol:'GLMR'},'1285':{name:'Moonriver',symbol:'MOVR'},'1329':{name:'Sei',symbol:'SEI'},'1625':{name:'Gravity Alpha',symbol:'G'},'1868':{name:'Soneium',symbol:'ETH'},'1923':{name:'Swellchain',symbol:'ETH'},'2020':{name:'Ronin',symbol:'RON'},'2222':{name:'Kava',symbol:'KAVA'},'2741':{name:'Abstract',symbol:'ETH'},'4200':{name:'Merlin',symbol:'BTC'},'4326':{name:'MegaETH',symbol:'ETH'},'5000':{name:'Mantle',symbol:'MNT'},'8217':{name:'Kaia',symbol:'KAIA'},'13371':{name:'Immutable zkEVM',symbol:'IMX'},'23294':{name:'Oasis Sapphire',symbol:'ROSE'},'33139':{name:'ApeChain',symbol:'APE'},'34443':{name:'Mode',symbol:'ETH'},'42170':{name:'Arbitrum Nova',symbol:'ETH'},'42220':{name:'Celo',symbol:'CELO'},'42793':{name:'Etherlink',symbol:'XTZ'},'48900':{name:'Zircuit',symbol:'ETH'},'57073':{name:'Ink',symbol:'ETH'},'59144':{name:'Linea',symbol:'ETH'},'60808':{name:'BOB',symbol:'ETH'},'80094':{name:'Berachain',symbol:'BERA'},'81457':{name:'Blast',symbol:'ETH'},'98866':{name:'Plume',symbol:'PLUME'},'167000':{name:'Taiko',symbol:'ETH'},'200901':{name:'Bitlayer',symbol:'BTC'},'534352':{name:'Scroll',symbol:'ETH'},'666666666':{name:'Degen Chain',symbol:'DEGEN'},'1313161554':{name:'Aurora',symbol:'ETH'},'1666600000':{name:'Harmony',symbol:'ONE'}});
const identity=(family,chainId,address)=>[family,chainId??'',family==='evm'?address.toLowerCase():address].join(':');
// The bundled registry is one string of tab separated rows, newline separated:
// networkIndex, address, name, symbol, decimals, icon, programIndex. It is split
// on first use, so a fresh VM that only signs a PSBT or a message pays nothing
// for thousands of token identities it will never look at.
let entries;
const index=()=>entries??=new Map(registry.assets.split('\n').map(row=>{
  const [network,assetAddress,name,symbol,decimals,icon,program]=row.split('\t');
  const [chainFamily,chainId]=registry.networks[+network];
  const asset={chainFamily,...(chainId?{chainId}:{}),assetAddress,name,symbol,decimals:+decimals,icon,
    ...(program==='-1'?{}:{tokenProgram:registry.programs[+program]})};
  return [identity(chainFamily,chainId,assetAddress),Object.freeze(asset)];
}));
/** What this device can say about an EVM network.
 *
 * The named ones carry a name and a native symbol, so a fee can be denominated
 * and a token identity looked up. An unnamed one is still signed: the chain ID
 * is inside what gets signed (EIP-155), and refusing a legitimate network does
 * not make anyone safer, it only makes the device useless there. What it cannot
 * do is invent a name or a ticker, so an unknown chain says so, prices nothing
 * in a guessed unit, and has no token registry behind it — every contract on it
 * reads as unregistered, which is exactly what it is here. */
export function evmNetwork(chainId) {
  const id=String(chainId);
  check(/^[0-9]+$/.test(id)&&id!=='0'&&BigInt(id)<=(1n<<64n)-1n,'NETWORK','Invalid EVM chain ID');
  if(NETWORKS[id])return {chainId:id,...NETWORKS[id],known:true};
  return {chainId:id,name:'Chain '+id,symbol:'native units',known:false};
}
export function lookupToken(chainFamily,chainId,assetAddress,rawAmount,tokenProgram) {
  const asset=index().get(identity(chainFamily,chainId,assetAddress));if(!asset)return undefined;
  if(tokenProgram&&asset.tokenProgram&&asset.tokenProgram!==tokenProgram)return undefined;
  const result={...asset};if(rawAmount!==undefined){result.rawAmount=String(rawAmount);result.displayAmount=decimal(rawAmount,asset.decimals);}return result;
}
export const tokenRegistryVersion=registry.registryVersion;
export const tokenRegistrySize=registry.assetCount;
